window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c444f23e2db30e1"]={"versions": [{"id": "FIG-9c444f23e2db30e1", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des makroskopischen Dokumentations- und Textmodells im Kontext des AUTOSAR Generic Structure Template (TPS GenericStructureTemplate). Das Metamodell beschreibt die hierarchische Strukturierung und Verankerung von Dokumentationselementen an AUTOSAR-Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Anbindungselement ist <code>DocumentationContainer</code> (Platzhalter für dokumentierbare AUTOSAR-Metamodellelemente). Vier Anbindungspunkte führen von <code>DocumentationContainer</code> über Kompositionen zu Dokumentationsstrukturen:</p>\n<ul class=\"fig-list\"><li><code>+addInfo</code> (0..1) bindet <code>PredefinedChapter</code> (Stereotyp <code>DocSection</code>) an.\n</li><li><code>+chapter</code> (0..1) bindet <code>Chapter</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>) an.\n</li><li><code>+introduction</code> (0..1) bindet <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) an.\n</li><li><code>+desc</code> bindet <code>Paragraph</code> an.\n</li></ul>\n<p class=\"fig-p\">Hierarchische Gliederung und Inhalte:</p>\n<ul class=\"fig-list\"><li><code>PredefinedChapter</code> und <code>Chapter</code> enthalten per Komposition (<code>+content</code>, Kardinalität 1) ein <code>ChapterModel</code>.\n</li><li><code>ChapterModel</code> enthält über Kompositionen:\n<ul class=\"fig-list\"><li>Unterkapitel <code>+chapter</code> (0..*) vom Typ <code>Chapter</code>,\n</li><li>Abschnitte <code>+topic1</code> (0..*) vom Typ <code>Topic</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>),\n</li><li>Kapitelinhalte <code>+chapterContent</code> (0..1) vom Typ <code>ChapterContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>ChapterContent</code> aggregiert bzw. komponiert <code>+topicContent</code> vom Typ <code>TopicContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li><li><code>Topic</code> komponiert <code>+topicContent</code> (0..1) vom Typ <code>TopicContent</code>.\n</li><li><code>TopicContent</code> aggregiert bzw. komponiert Block- und Tabellenelemente:\n<ul class=\"fig-list\"><li><code>+prms</code> vom Typ <code>Prms</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+table</code> vom Typ <code>Table</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+blockLevelContent</code> vom Typ <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code> komponiert Textabsätze <code>+p</code> vom Typ <code>Paragraph</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Dekomposition von Dokumentationsbehältern über Kapitel, Topics und Dokumentationsblöcke bis hin zu Absätzen und Tabellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln für AUTOSAR-M2-Modelle zur technischen Dokumentation:</p>\n<ul class=\"fig-list\"><li>Die Anbindung von Dokumentation erfolgt auf vier Granularitätsstufen: Gesamtkapitel (<code>Chapter</code>, <code>PredefinedChapter</code>), Einleitungsblöcke (<code>DocumentationBlock</code>) und Einzelbeschreibungen (<code>Paragraph</code>).\n</li><li>Mixed-Content-Klassen (<code>«atpMixed»</code>: <code>ChapterContent</code>, <code>TopicContent</code>, <code>DocumentationBlock</code>) erlauben freie Textauszeichnung und gemischte Inhalte nach AUTOSAR-XML-Serialisierungsregeln.\n</li><li>Tabellenstrukturen (<code>Table</code>, <code>Prms</code>) sind als <code>DocTable</code> typisiert. <code>Chapter</code> und <code>Topic</code> erben als <code>Identifiable</code> Identifikationsattribute (<code>shortName</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-15502302f2f3a71a", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des makroskopischen Dokumentations- und Textmodells im Kontext des AUTOSAR Generic Structure Template (TPS GenericStructureTemplate). Das Metamodell beschreibt die hierarchische Strukturierung und Verankerung von Dokumentationselementen an AUTOSAR-Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Anbindungselement ist <code>DocumentationContainer</code> (Platzhalter für dokumentierbare AUTOSAR-Metamodellelemente). Vier Anbindungspunkte führen von <code>DocumentationContainer</code> über Kompositionen zu Dokumentationsstrukturen:</p>\n<ul class=\"fig-list\"><li><code>+addInfo</code> (0..1) bindet <code>PredefinedChapter</code> (Stereotyp <code>DocSection</code>) an.\n</li><li><code>+chapter</code> (0..1) bindet <code>Chapter</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>) an.\n</li><li><code>+introduction</code> (0..1) bindet <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) an.\n</li><li><code>+desc</code> bindet <code>Paragraph</code> an.\n</li></ul>\n<p class=\"fig-p\">Hierarchische Gliederung und Inhalte:</p>\n<ul class=\"fig-list\"><li><code>PredefinedChapter</code> und <code>Chapter</code> enthalten per Komposition (<code>+content</code>, Kardinalität 1) ein <code>ChapterModel</code>.\n</li><li><code>ChapterModel</code> enthält über Kompositionen:\n<ul class=\"fig-list\"><li>Unterkapitel <code>+chapter</code> (0..*) vom Typ <code>Chapter</code>,\n</li><li>Abschnitte <code>+topic1</code> (0..*) vom Typ <code>Topic</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>),\n</li><li>Kapitelinhalte <code>+chapterContent</code> (0..1) vom Typ <code>ChapterContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>ChapterContent</code> aggregiert bzw. komponiert <code>+topicContent</code> vom Typ <code>TopicContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li><li><code>Topic</code> komponiert <code>+topicContent</code> (0..1) vom Typ <code>TopicContent</code>.\n</li><li><code>TopicContent</code> aggregiert bzw. komponiert Block- und Tabellenelemente:\n<ul class=\"fig-list\"><li><code>+prms</code> vom Typ <code>Prms</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+table</code> vom Typ <code>Table</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+blockLevelContent</code> vom Typ <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code> komponiert Textabsätze <code>+p</code> vom Typ <code>Paragraph</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Dekomposition von Dokumentationsbehältern über Kapitel, Topics und Dokumentationsblöcke bis hin zu Absätzen und Tabellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln für AUTOSAR-M2-Modelle zur technischen Dokumentation:</p>\n<ul class=\"fig-list\"><li>Die Anbindung von Dokumentation erfolgt auf vier Granularitätsstufen: Gesamtkapitel (<code>Chapter</code>, <code>PredefinedChapter</code>), Einleitungsblöcke (<code>DocumentationBlock</code>) und Einzelbeschreibungen (<code>Paragraph</code>).\n</li><li>Mixed-Content-Klassen (<code>«atpMixed»</code>: <code>ChapterContent</code>, <code>TopicContent</code>, <code>DocumentationBlock</code>) erlauben freie Textauszeichnung und gemischte Inhalte nach AUTOSAR-XML-Serialisierungsregeln.\n</li><li>Tabellenstrukturen (<code>Table</code>, <code>Prms</code>) sind als <code>DocTable</code> typisiert. <code>Chapter</code> und <code>Topic</code> erben als <code>Identifiable</code> Identifikationsattribute (<code>shortName</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-33e6a14eaa0d4a40", "releases": ["R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des makroskopischen Dokumentations- und Textmodells im Kontext des AUTOSAR Generic Structure Template (TPS GenericStructureTemplate). Das Metamodell beschreibt die hierarchische Strukturierung und Verankerung von Dokumentationselementen an AUTOSAR-Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Anbindungselement ist <code>DocumentationContainer</code> (Platzhalter für dokumentierbare AUTOSAR-Metamodellelemente). Vier Anbindungspunkte führen von <code>DocumentationContainer</code> über Kompositionen zu Dokumentationsstrukturen:</p>\n<ul class=\"fig-list\"><li><code>+addInfo</code> (0..1) bindet <code>PredefinedChapter</code> (Stereotyp <code>DocSection</code>) an.\n</li><li><code>+chapter</code> (0..1) bindet <code>Chapter</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>) an.\n</li><li><code>+introduction</code> (0..1) bindet <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) an.\n</li><li><code>+desc</code> bindet <code>Paragraph</code> an.\n</li></ul>\n<p class=\"fig-p\">Hierarchische Gliederung und Inhalte:</p>\n<ul class=\"fig-list\"><li><code>PredefinedChapter</code> und <code>Chapter</code> enthalten per Komposition (<code>+content</code>, Kardinalität 1) ein <code>ChapterModel</code>.\n</li><li><code>ChapterModel</code> enthält über Kompositionen:\n<ul class=\"fig-list\"><li>Unterkapitel <code>+chapter</code> (0..*) vom Typ <code>Chapter</code>,\n</li><li>Abschnitte <code>+topic1</code> (0..*) vom Typ <code>Topic</code> (Stereotypen <code>DocSection</code>, <code>Identifiable</code>),\n</li><li>Kapitelinhalte <code>+chapterContent</code> (0..1) vom Typ <code>ChapterContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>ChapterContent</code> aggregiert bzw. komponiert <code>+topicContent</code> vom Typ <code>TopicContent</code> (Stereotyp <code>«atpMixed»</code>).\n</li><li><code>Topic</code> komponiert <code>+topicContent</code> (0..1) vom Typ <code>TopicContent</code>.\n</li><li><code>TopicContent</code> aggregiert bzw. komponiert Block- und Tabellenelemente:\n<ul class=\"fig-list\"><li><code>+prms</code> vom Typ <code>Prms</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+table</code> vom Typ <code>Table</code> (Stereotyp <code>DocTable</code>),\n</li><li><code>+traceableTable</code> vom Typ <code>RequirementsTracing::TraceableTable</code> (Stereotypen <code>Identifiable</code>, <code>Paginateable</code>, <code>Traceable</code>),\n</li><li><code>+blockLevelContent</code> vom Typ <code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>).\n</li></ul>\n</li><li><code>RequirementsTracing::TraceableTable</code> aggregiert bzw. komponiert über die Rolle <code>+table</code> (Kardinalität 1) eine <code>Table</code>.\n</li><li><code>DocumentationBlock</code> komponiert Textabsätze <code>+p</code> vom Typ <code>Paragraph</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Dekomposition von Dokumentationsbehältern über Kapitel, Topics und Dokumentationsblöcke bis hin zu Absätzen und Tabellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln für AUTOSAR-M2-Modelle zur technischen Dokumentation:</p>\n<ul class=\"fig-list\"><li>Die Anbindung von Dokumentation erfolgt auf vier Granularitätsstufen: Gesamtkapitel (<code>Chapter</code>, <code>PredefinedChapter</code>), Einleitungsblöcke (<code>DocumentationBlock</code>) und Einzelbeschreibungen (<code>Paragraph</code>).\n</li><li>Mixed-Content-Klassen (<code>«atpMixed»</code>: <code>ChapterContent</code>, <code>TopicContent</code>, <code>DocumentationBlock</code>) erlauben freie Textauszeichnung und gemischte Inhalte nach AUTOSAR-XML-Serialisierungsregeln.\n</li><li>Tabellenstrukturen umfassen generische Tabellen (<code>Table</code>), Parametertabellen (<code>Prms</code>) sowie rückverfolgbare Tabellen (<code>RequirementsTracing::TraceableTable</code>), welche <code>Table</code> einbinden und Identifizierbarkeit (<code>Identifiable</code>), Paginierbarkeit (<code>Paginateable</code>) und Anforderungsrückverfolgbarkeit (<code>Traceable</code>) bereitstellen. <code>Chapter</code> und <code>Topic</code> erben als <code>Identifiable</code> Identifikationsattribute (<code>shortName</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9c444f23e2db30e1", "to": "FIG-15502302f2f3a71a", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-15502302f2f3a71a", "to": "FIG-33e6a14eaa0d4a40", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Element <code>RequirementsTracing::TraceableTable</code> (mit Stereotypen <code>Identifiable</code>, <code>Paginateable</code>, <code>Traceable</code>) hinzugefügt.\n</li><li>Komposition von <code>TopicContent</code> zu <code>RequirementsTracing::TraceableTable</code> mit Rollenname <code>+traceableTable</code> hinzugefügt.\n</li><li>Komposition von <code>RequirementsTracing::TraceableTable</code> zu <code>Table</code> mit Rollenname <code>+table</code> und Kardinalität <code>1</code> hinzugefügt.\n</li></ul>"}]};
